      "content": "from __future__ import annotations

from typing import Sequence, Tuple, List
from ledgerlib.round_div import round_div

def vat_summary(lines: Sequence[Tuple[int, int]]) -> List[Tuple[int, int, int]]:
    """
    Summarise invoice lines by VAT rate.

    Each line is (net_amount, vat_rate_basis_points).
    Returns a list of (vat_rate, total_net, total_vat) sorted by vat_rate.
    VAT is computed once per rate on the summed net amount and rounded half-up.

    Raises ValueError if vat_rate_basis_points < 0.
    """
    rates_map = {}
    for net, rate in lines:
        if rate < 0:
            raise ValueError("VAT rate cannot be negative")
        rates_map[rate] = rates_map.get(rate, 0) + net

    summary = []
    for rate in sorted(rates_map.keys()):
        total_net = rates_map[rate]
        # VAT = total_net * rate / 10000
        total_vat = round_div(total_net * rate, 10000, mode="half_up")
        summary.append((rate, total_net, total_vat))

    return summary
"
