import re

def parse_amount(text: str) -> int:
    """
    Parses a money string such as '-$1,234.56' into integer cents.

    - Supports optional sign (+/-) and currency symbol ($).
    - Commas are only accepted in real thousands positions.
    - Exactly two decimal places are allowed, or no decimal point (implies .00).
    - Raises ValueError for invalid formats.
    """
    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    sign = 1
    if text.startswith('+'):
        text = text[1:]
    elif text.startswith('-'):
        sign = -1
        text = text[1:]

    if text.startswith('$'):
        text = text[1:]

    if not text:
        raise ValueError("No numeric value found")

    parts = text.split('.')
    if len(parts) > 2:
        raise ValueError("Too many decimal points")

    int_part = parts[0]
    frac_part = parts[1] if len(parts) == 2 else "00"

    if len(frac_part) > 2:
        raise ValueError("Too many decimal places")
    if not frac_part.isdigit():
        raise ValueError("Invalid characters in fractional part")

    # Standard padding: .5 -> .50
    if len(frac_part) == 1:
        frac_part = frac_part + '0'

    if not int_part:
        # Handle cases like '.50'
        pass
    else:
        if ',' in int_part:
            groups = int_part.split(',')
            if not (1 <= len(groups[0]) <= 3) or not groups[0].isdigit():
                raise ValueError("Invalid comma position")
            for group in groups[1:]:
                if len(group) != 3 or not group.isdigit():
                    raise ValueError("Invalid comma position")
        else:
            if not int_part.isdigit():
                raise ValueError("Invalid characters in integer part")

    clean_int = int_part.replace(',', '')
    total_cents = int(f"{clean_int or '0'}{frac_part}")

    return total_cents * sign
"}}}
