        matched = False
        for ref in refs:
            if ref in remaining_invoices:
                results[line_id] = ref
                del remaining_invoices[ref]
                matched = True
                break
        if not matched:
            unmatched_lines.append((line_id, amount_str, description))

    # Second pass: Amount matches (only if unique among remaining)
    for line_id, amount_str, description in unmatched_lines:
        amount = parse_amount(amount_str)
        matches = [inv_id for inv_id, inv_amt in remaining_invoices.items() if inv_amt == amount]

        if len(matches) == 1:
            inv_id = matches[0]
            results[line_id] = inv_id
            del remaining_invoices[inv_id]
        else:
            results[line_id] = None

    # Ensure all original lines are in results
    for line_id, _, _ in bank_lines:
        if line_id not in results:
            results[line_id] = None

    return results
